db:select.db:input-parameters:
 #[{

				entityCode: vars.entityCode default p('compliance.entityCode'),

				reportType: vars.reportType default p('compliance.reportType'),

				manualPeriodEnd: vars.manualPeriodEnd

			}]

ee:variables.ee:set-variable:
 %dw 2.0

output application/json

fun parseDateTimeSafe(val: Any) = 

  if (val == null) null

  else if (val is DateTime) val

  else if (val is LocalDateTime) val as DateTime

  else (((val as String) replace " " with "T") as DateTime) default (now())



var ctrl = vars.controlRecord[0] default {}

var entityCode = vars.entityCode default ctrl.entity_code default p('compliance.entityCode')

var entityName = p('compliance.entityName')

var reportType = vars.reportType default ctrl.report_type default p('compliance.reportType')

var currency = p('compliance.currency')



// Check if manual historical period was provided

var isManual = vars.manualPeriodStart != null and vars.manualPeriodEnd != null

var isReprocess = vars.isHistoricalReprocess default false



var lastSuccessEnd = if (ctrl.last_success_period_end != null) parseDateTimeSafe(ctrl.last_success_period_end) else null



var periodStart = if (isManual) (vars.manualPeriodStart as String)

                  else if (lastSuccessEnd != null) 

                    ((lastSuccessEnd + |PT1S|) as String {format: "yyyy-MM-dd HH:mm:ss"})

                  else "2026-09-11 00:00:00"



var periodEnd = if (isManual) (vars.manualPeriodEnd as String)

                else if (lastSuccessEnd != null)

                  (((lastSuccessEnd + |P1D|) as String {format: "yyyy-MM-dd"}) ++ " 23:59:59")

                else "2026-09-11 23:59:59"



// Concurrency-safe, monotonically incrementing sequence calculation:

// If prior runs exist for this reporting period (revisions, retries, or manual runs), advance past the maximum existing sequence.

var maxPeriodSeq = (ctrl.max_period_sequence default 0) as Number

var ctrlSeq = (ctrl.current_sequence_number default 0) as Number

var baseSeq = if (maxPeriodSeq > 0) maxPeriodSeq else ctrlSeq

var nextSeq = baseSeq + 1

var runId = "RUN-" ++ (now() as String {format: "yyyyMMdd-HHmmss"}) ++ "-" ++ (uuid()[0 to 5])

---

{

	runId: runId,

	entityCode: entityCode,

	entityName: entityName,

	reportType: reportType,

	currency: currency,

	periodStart: periodStart,

	periodEnd: periodEnd,

	sequenceNumber: nextSeq,

	isRevision: isReprocess or isManual,

	triggerSource: vars.triggerSource default "SCHEDULED",

	correlationId: vars.correlationId default correlationId,

	generatedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}

}

